def _ssl_context(verify: bool) -> ssl.SSLContext:
    if verify:
        return ssl.create_default_context()
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    return ctx


def http_request(
    method: str,
    url: str,
    *,
    query: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
    body: bytes | None = None,
    use_proxy: bool = False,
    user_agent: str | None = None,
    verify_ssl: bool = True,
    timeout: float | None = None,
    retry_403: bool = True,
    expect_json: bool = True,
) -> dict[str, Any]:
    if use_proxy and PROXY_URL and PROXY_API_KEY:
        return http_via_proxy(method, url, query or {}, headers or {}, body)

    request_url = url
    if query:
        sep = "&" if "?" in url else "?"
        request_url = url + sep + urllib.parse.urlencode(query)

    ua = user_agent or USER_AGENT
    hdrs = {
        "Accept": "application/json",
        "User-Agent": ua,
    }
    if headers:
        hdrs.update(headers)

    to = timeout if timeout is not None else float(HTTP_TIMEOUT_SEC)
    max_attempts = 1 + REQUEST_RETRY_COUNT
    last_error: Exception | None = None

    for attempt in range(1, max_attempts + 1):
        req = urllib.request.Request(
            request_url, data=body, headers=hdrs, method=method.upper()
        )
        ctx = _ssl_context(verify_ssl)
        try:
            with urllib.request.urlopen(req, timeout=to, context=ctx) as resp:
                raw = resp.read().decode("utf-8", errors="replace")
                status = getattr(resp, "status", 200) or 200
        except urllib.error.HTTPError as e:
            raw = e.read().decode("utf-8", errors="replace") if e.fp else ""
            status = e.code
            if status == 403 and retry_403 and ua != USER_AGENT_POSTMAN:
                return http_request(
                    method,
                    url,
                    query=query,
                    headers=headers,
                    body=body,
                    use_proxy=False,
                    user_agent=USER_AGENT_POSTMAN,
                    verify_ssl=verify_ssl,
                    timeout=timeout,
                    retry_403=False,
                    expect_json=expect_json,
                )
            last_error = RuntimeError(f"HTTP {status} for {request_url}: {raw[:300]}")
            if attempt < max_attempts:
                time.sleep((REQUEST_RETRY_BASE_MS * (2 ** (attempt - 1))) / 1000.0)
                continue
            raise last_error from e
        except Exception as e:
            last_error = RuntimeError(f"Request failed for {request_url}: {e}")
            if attempt < max_attempts:
                time.sleep((REQUEST_RETRY_BASE_MS * (2 ** (attempt - 1))) / 1000.0)
                continue
            raise last_error from e

        if status < 200 or status >= 300:
            last_error = RuntimeError(f"HTTP {status} for {request_url}: {raw[:300]}")
            if attempt < max_attempts:
                time.sleep((REQUEST_RETRY_BASE_MS * (2 ** (attempt - 1))) / 1000.0)
                continue
            raise last_error

        json_data: Any = None
        if raw and expect_json:
            try:
                json_data = json.loads(raw)
            except json.JSONDecodeError as e:
                raise RuntimeError(f"Invalid JSON from {request_url}") from e

        return {"status": status, "body": raw, "json": json_data}

    raise last_error or RuntimeError(f"Request failed for {request_url}")


def http_via_proxy(
    method: str,
    url: str,
    query: dict[str, Any],
    headers: dict[str, str],
    body: bytes | None,
) -> dict[str, Any]:
    if not PROXY_URL or not PROXY_API_KEY:
        raise RuntimeError("PROXY_URL / PROXY_API_KEY required for proxy request")

    body_obj: Any = {}
    if body:
        try:
            body_obj = json.loads(body.decode("utf-8"))
        except (json.JSONDecodeError, UnicodeDecodeError):
            body_obj = {}

    payload = json.dumps(
        {
            "url": url,
            "method": method.upper(),
            "params": query,
            "body": body_obj,
            "headers": {
                "Accept": "application/json",
                "User-Agent": USER_AGENT,
                **headers,
            },
            "timeout": HTTP_TIMEOUT_SEC * 1000,
        }
    ).encode("utf-8")

    result = http_request(
        "POST",
        PROXY_URL,
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json",
            "x-api-key": PROXY_API_KEY,
        },
        body=payload,
        verify_ssl=SSL_VERIFY_EXCHANGE,
        timeout=float(max(HTTP_TIMEOUT_SEC, 60)),
        retry_403=False,
    )

    data = result["json"]
    if isinstance(data, dict):
        data = data.get("data", data.get("body", data))
    if isinstance(data, str):
        try:
            data = json.loads(data)
        except json.JSONDecodeError:
            pass

    return {
        "status": result["status"],
        "body": data if isinstance(data, str) else json.dumps(data),
        "json": data,
    }


def http_get_json(
    url: str,
    query: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
    use_proxy: bool = False,
) -> Any:
    return http_request(
        "GET",
        url,
        query=query,
        headers=headers,
        use_proxy=use_proxy,
        verify_ssl=SSL_VERIFY_EXCHANGE,
    )["json"]


def http_get_text(url: str, headers: dict[str, str] | None = None) -> str:
    """Fetch a non-JSON body (HTML pages)."""
    return http_request(
        "GET",
        url,
        headers=headers,
        verify_ssl=SSL_VERIFY_EXCHANGE,
        expect_json=False,
    )["body"]


def ingest_request(method: str, url_path: str, body: dict[str, Any] | None = None) -> Any:
    if not INGEST_SECRET:
        raise RuntimeError("INGEST_SECRET is required")
    if not url_path or url_path == "/":
        url = INGEST_URL
    else:
        url = f"{INGEST_URL}{url_path if url_path.startswith('/') else '/' + url_path}"
    headers = {
        "Accept": "application/json",
        "Authorization": f"Bearer {INGEST_SECRET}",
        "User-Agent": "irancrypto-tracker-py/1.0",
    }
    payload: bytes | None = None
    if body is not None:
        headers["Content-Type"] = "application/json"
        payload = json.dumps(body, ensure_ascii=False).encode("utf-8")

    result = http_request(
        method,
        url,
        headers=headers,
        body=payload,
        verify_ssl=SSL_VERIFY_INGEST,
        timeout=float(max(HTTP_TIMEOUT_SEC, 60)),
        retry_403=False,
    )
    return result["json"] if result["json"] is not None else {}


def wait_for_ingest_ready(run_id: str, logger: RunLogger | None = None) -> dict[str, Any]:
    deadline = time.monotonic() + FINALIZE_WAIT_SEC
    while True:
        status = ingest_request(
            "GET", f"/status?run_id={urllib.parse.quote(run_id)}"
        )
        if not isinstance(status, dict):
            status = {}
        missing = status.get("missing") if isinstance(status.get("missing"), list) else []
        if len(missing) == 0:
            log_info(f"Ingest ready for {run_id}")
            if logger is not None:
                logger.event("status_ready", {"run_id": run_id})
            return status
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            log_info(
                f"Finalize wait deadline reached for {run_id}; "
                f"proceeding with available sources (missing: {','.join(str(m) for m in missing)})"
            )
            if logger is not None:
                logger.event(
                    "status_timeout",
                    {
                        "run_id": run_id,
                        "missing": missing,
                        "waited_sec": FINALIZE_WAIT_SEC,
                    },
                )
            return status
        sleep_sec = min(FINALIZE_POLL_SEC, max(1, int(remaining)))
        log_info(
            f"Waiting for sources ({','.join(str(m) for m in missing)}); "
            f"poll in {sleep_sec}s"
        )
        if logger is not None:
            logger.event(
                "status_wait",
                {
                    "run_id": run_id,
                    "missing": missing,
                    "sleep_ms": sleep_sec * 1000,
                },
            )
        time.sleep(sleep_sec)


def finalize_when_ready(run_id: str, logger: RunLogger | None = None) -> Any:
    t0 = time.monotonic()
    wait_for_ingest_ready(run_id, logger)
    res = ingest_request("POST", "/finalize", {"run_id": run_id, "stage": "all"})
    if logger is not None:
        logger.event(
            "finalize_ok",
            {"run_id": run_id, "ms": int((time.monotonic() - t0) * 1000)},
        )
    log_info("Finalize complete")
    return res


