# --- ariomex ---

def parse_ariomex_list(lst: list, coins: list[str]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for row in lst:
        if not isinstance(row, dict) or not row.get("last_price"):
            continue
        symbol = str(row.get("base") or "").upper()
        if not symbol or not coin_allowed(coins, symbol):
            continue
        coin_volume = num(row.get("volume", 0))
        price_irt = num(row.get("last_price"))
        volume_irt = coin_volume * price_irt
        out.append(
            {
                "currency": "IRR",
                "symbol": symbol,
                "price": num(row["last_price"], {"decimalPlaces": 8, "multiply": 10}),
                "volume_1d": num(volume_irt, {"multiply": 10, "roundUp": True}),
                "coin_volume_1d": coin_volume,
                "change_1d": num(row.get("change_percentage", 0), {"decimalPlaces": 2}),
                "source": "ariomex",
            }
        )
    return out


def scrape_ariomex(coins: list[str]) -> list[dict[str, Any]]:
    all_rows: list[Any] = []
    max_rows = 200
    max_pages = 20
    for page in range(1, max_pages + 1):
        response = http_get_json(
            "https://data.ariomex.ir/exchange_data/markets_details",
            query={
                "maxRowsPerPage": max_rows,
                "page": page,
                "resolution": "1d",
                "quote": "irt",
            },
        )
        if not isinstance(response, dict) or response.get("status") != "true":
            raise RuntimeError("Ariomex: invalid status")
        lst = response.get("result")
        if not isinstance(lst, list) or not lst:
            break
        all_rows.extend(lst)
        if len(lst) < max_rows:
            break
    if not all_rows:
        raise RuntimeError("Ariomex: empty")
    return parse_ariomex_list(all_rows, coins)


def register_ariomex() -> dict[str, Any]:
    return {
        "coin_use": "all",
        "scrape": scrape_ariomex,
    }

# --- arzpaya ---

def scrape_arzpaya(coins: list[str]) -> list[dict[str, Any]]:
    popular_coins = ["BTC", "ETH", "USDT", "LTC", "BCH", "TRX", "DOGE", "LINK", "XRP", "SOL", "ADA"]
    target_coins = coins if coins else popular_coins
    out: list[dict[str, Any]] = []

    for coin in target_coins:
        if coin.upper() in ("IRT", "IRR"):
            continue
        try:
            url = f"https://na1.arzpaya.com/orderbook/buy/irt/{coin.lower()}"
            res = http_get_json(url)
            if isinstance(res, dict) and isinstance(res.get("Data"), list) and res["Data"]:
                top_bid = res["Data"][0]
                price = num(top_bid.get("p"), {"multiply": 10, "decimalPlaces": 8})
                if price > 0:
                    out.append({
                        "currency": "IRR",
                        "symbol": coin.upper(),
                        "price": price,
                        "volume_1d": 0,
                        "coin_volume_1d": 0,
                        "change_1d": 0,
                        "source": "arzpaya",
                    })
        except Exception:
            pass

    return out


def register_arzpaya() -> dict[str, Any]:
    return {
        "coin_use": "all",
        "scrape": scrape_arzpaya,
    }

# --- bidarz ---

def parse_bidarz_page(html: str, coin: str) -> dict[str, Any] | None:
    """Parse the IRT ticker embedded in a Bidarz price page (`quoteId:"IRR"` is labelled Toman,
    and its prices and volume are in Toman).
    Returns None when the market is missing, idle for 24h, or too imprecise.
    """
    # Bidarz rounds Toman prices to whole units; below this the rounding error exceeds 1%.
    min_price_toman = 100

    ticker_match = re.search(r'\{[^{}]*quoteId:"IRR"[^{}]*\}', html)
    if not ticker_match:
        return None
    ticker = ticker_match.group(0)

    def field(key: str) -> float:
        m = re.search(r"[{,]" + key + r':"?(-?[0-9]*\.?[0-9]+)', ticker)
        return float(m.group(1)) if m else 0.0

    price_toman = field("last")
    # A zero 24h high means no trades, so `last` is stale.
    if price_toman < min_price_toman or field("max24h") <= 0:
        return None

    volume_toman = field("volume24h")
    return {
        "currency": "IRR",
        "symbol": coin.upper(),
        "price": num(price_toman, {"multiply": 10, "decimalPlaces": 8}),
        "volume_1d": num(volume_toman, {"multiply": 10, "roundUp": True}),
        "coin_volume_1d": num(volume_toman, {"divide": price_toman}),
        "change_1d": num(field("changePercent24h"), {"decimalPlaces": 2}),
        "change_7d": num(field("changePercent7d"), {"decimalPlaces": 2}),
        "source": "bidarz",
    }


def scrape_bidarz(coins: list[str]) -> list[dict[str, Any]]:
    popular_coins = ["BTC", "ETH", "USDT", "LTC", "BCH", "TRX", "DOGE", "LINK", "XRP", "SOL", "ADA"]
    out: list[dict[str, Any]] = []

    for coin in coins or popular_coins:
        if coin.upper() in ("IRT", "IRR"):
            continue
        try:
            row = parse_bidarz_page(http_get_text(f"https://bidarz.ir/price/{coin.lower()}"), coin)
        except Exception:
            continue
        if row is not None:
            out.append(row)

    return out


def register_bidarz() -> dict[str, Any]:
    return {
        "coin_use": "all",
        "scrape": scrape_bidarz,
    }

# --- bitimen ---

def parse_bitimen(data: Any, coins: list[str]) -> list[dict[str, Any]]:
    if not isinstance(data, dict) or not data:
        raise RuntimeError("Bitimen: empty response")
    out: list[dict[str, Any]] = []
    for key, item in data.items():
        if not isinstance(item, dict):
            continue
        symbol = str(item.get("base_asset_ticker", "")).upper()
        if not symbol or not coin_allowed(coins, symbol):
            continue
        raw_price = item.get("last_price") or item.get("best_bid_raw") or 0
        price = num(raw_price, {"multiply": 10, "decimalPlaces": 8})
        raw_vol = str(item.get("volume", "0") or "0").replace(",", "")
        volume_1d = num(raw_vol, {"multiply": 10, "roundUp": True})
        change_1d = num(item.get("change_display") or item.get("change") or 0, {"decimalPlaces": 2})

        out.append({
            "currency": "IRR",
            "symbol": symbol,
            "price": price,
            "volume_1d": volume_1d,
            "coin_volume_1d": 0,
            "change_1d": change_1d,
            "source": "bitimen",
        })

    return out


