# --- bitmax ---

def parse_bitmax(data: Any, coins: list[str]) -> list[dict[str, Any]]:
    msg = data.get("message") if isinstance(data, dict) and "message" in data else data
    if not isinstance(msg, dict) or not msg or (isinstance(data, dict) and data.get("error")):
        raise RuntimeError("BitMax: empty/error")
    usdt = 0.0
    if isinstance(msg.get("USDT"), dict) and msg["USDT"].get("price_in_irt"):
        usdt = num(msg["USDT"]["price_in_irt"], {"decimalPlaces": 8, "multiply": 10})
    out: list[dict[str, Any]] = []
    for symbol_key, row in msg.items():
        if not isinstance(row, dict) or not row.get("price_in_irt"):
            continue
        symbol = str(symbol_key).upper()
        if not coin_allowed(coins, symbol):
            continue
        out.append(
            {
                "currency": "IRR",
                "symbol": symbol,
                "price": num(row["price_in_irt"], {"decimalPlaces": 8, "multiply": 10}),
                # volume_24h is the global market volume (CoinMarketCap mirror), not BitMax's own trading
                "volume_1d": 0,
                "coin_volume_1d": 0,
                "change_1d": num(row.get("change", 0), {"decimalPlaces": 2}),
                "change_7d": num(row.get("change_7d", 0), {"decimalPlaces": 2}),
                "market_cap": num(row.get("market_cap", 0), {"multiply": usdt, "roundUp": True}),
                "source": "bitmax",
            }
        )
    return out


def job_bitmax() -> dict[str, Any]:
    return {"url": "https://api.bitmax.ir/watcher/price/alternative"}


def register_bitmax() -> dict[str, Any]:
    return {
        "coin_use": "all",
        "job": job_bitmax,
        "parse": parse_bitmax,
    }

# --- bitpin ---

def parse_bitpin_list(lst: list, coins: list[str]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for row in lst:
        if not isinstance(row, dict):
            continue
        c2 = row.get("currency2") or {}
        c1 = row.get("currency1") or {}
        ob = row.get("order_book_info") or {}
        if c2.get("code") != "IRT":
            continue
        if c1.get("forTest") or not ob.get("price"):
            continue
        symbol = str(c1.get("code") or "").upper()
        if not symbol or not coin_allowed(coins, symbol):
            continue
        created = (row.get("internal_price_info") or {}).get("created_at")
        ts = int(num(created, {"roundUp": True})) if created else int(time.time())
        out.append(
            {
                "currency": "IRR",
                "symbol": symbol,
                "price": num(ob["price"], {"decimalPlaces": 8, "multiply": 10}),
                "volume_1d": num(ob.get("value", 0), {"multiply": 10, "roundUp": True}),
                "coin_volume_1d": num(ob.get("amount", 0)),
                "change_1d": num(ob.get("change", 0), {"decimalPlaces": 2}),
                "source": "bitpin",
                "last_update": {"date": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(ts)), "timestamp": ts},
            }
        )
    return out


def scrape_bitpin(coins: list[str]) -> list[dict[str, Any]]:
    """Follow Django-style `next` pagination (and page=N fallback)."""
    all_rows: list[Any] = []
    next_url: str | None = None
    page = 1
    max_pages = 50

    for _ in range(max_pages):
        if next_url:
            result = http_get_json(next_url)
        else:
            query = {"page": page} if page > 1 else None
            result = http_get_json(
                "https://api.bitpin.ir/v1/mkt/markets/",
                query=query,
            )
        if not isinstance(result, dict) or not isinstance(result.get("results"), list):
            raise RuntimeError("Bitpin: invalid response")
        rows = result["results"]
        if not rows and not all_rows:
            raise RuntimeError("Bitpin: empty")
        all_rows.extend(rows)

        nxt = result.get("next")
        if isinstance(nxt, str) and nxt:
            next_url = nxt
            continue

        count = int(result.get("count") or 0)
        if count > 0 and len(all_rows) < count and len(rows) > 0:
            next_url = None
            page += 1
            continue
        break

    if not all_rows:
        raise RuntimeError("Bitpin: empty")
    return parse_bitpin_list(all_rows, coins)


def register_bitpin() -> dict[str, Any]:
    return {
        "coin_use": "all",
        "scrape": scrape_bitpin,
    }

